CREATE OR REPLACE FUNCTION get_donor_renal_score(p_donor_id text)
RETURNS numeric AS $$
DECLARE
    v_cr numeric;
    v_gfr numeric;
BEGIN
    SELECT SPLIT_PART(don_crtn_val, ' ', 1)::numeric, SPLIT_PART(don_gfr_val, ' ', 1)::numeric
    INTO v_cr, v_gfr
    FROM function_and_recovery
    WHERE recov_don_registry = p_donor_id;

    RETURN ROUND(CAST((1.0 * v_gfr) - (10.0 * v_cr) AS numeric), 2);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_donor_renal_score(p_donor_id text)
RETURNS numeric AS $$
DECLARE
    v_score numeric;
BEGIN
    SELECT INTO v_score (1.0 * SPLIT_PART(don_gfr_val, ' ', 1)::numeric) - (10.0 * SPLIT_PART(don_crtn_val, ' ', 1)::numeric)
    FROM function_and_recovery
    WHERE recov_don_registry = p_donor_id;

    RETURN ROUND(v_score::numeric, 2);
END;
$$ LANGUAGE plpgsql;

